BEGIN
  IF p_user_id IS NULL OR p_store_id IS NULL THEN RETURN false; END IF;
  -- Nivel administrativo de plataforma (admin|superadmin) delegado al check
  -- central is_admin_check — la misma fuente confiable de is_admin()/RLS
  -- (20261027120000 has_store_access_as_superadmin_policy).
  IF public.is_admin_check(p_user_id) THEN RETURN true; END IF;
  -- Membresía operativa de GESTIÓN en la tienda específica (canManageStore):
  -- clerk/warehouse/usuario/costo NO gestionan.
  RETURN EXISTS (
    SELECT 1 FROM public.user_store_memberships m
    WHERE m.user_id = p_user_id
      AND m.store_id = p_store_id
      AND m.status = 'active'
      AND m.role IN ('admin', 'manager', 'encargado')
  );
END;

BEGIN
  IF auth.uid() IS NULL OR p_store_id IS NULL THEN RETURN false; END IF;
  -- superadmin de plataforma: alcance GLOBAL (incluye tiendas inactivas;
  -- privilegio administrativo legítimo de plataforma)
  IF public.is_superadmin() THEN RETURN true; END IF;
  -- admin de plataforma: EXCLUSIVAMENTE tiendas activas de su tenant
  -- (el alcance lo codifica current_user_store_ids(): admin → su tenant)
  IF public.is_admin() AND p_store_id = ANY(public.current_user_store_ids()) THEN
    RETURN true;
  END IF;
  -- admin de tienda: membresía ACTIVA con rol 'admin' en esa tienda
  RETURN EXISTS (
    SELECT 1 FROM public.user_store_memberships m
    WHERE m.user_id = auth.uid()
      AND m.store_id = p_store_id
      AND m.status = 'active'
      AND m.role = 'admin'
  );
END;

DECLARE
  v_entry uuid;
  v_residual numeric;
BEGIN
  -- Solo transiciones de anulación (estado previo vivo → voided/reversed).
  IF NEW.status NOT IN ('voided', 'reversed') OR OLD.status IN ('voided', 'reversed') THEN
    RETURN NEW;
  END IF;
  -- ¿Algún asiento posted (reconocimiento/pago) con reversión parcial enlazada?
  -- (las recepciones pending no tienen asientos → flujo ordinario intacto)
  SELECT e.id, public.fin_entry_reversal_residual(e.id)
    INTO v_entry, v_residual
  FROM public.fin_entries e
  WHERE e.document_type = 'RECEPCION' AND e.document_id = NEW.id
    AND e.status = 'posted' AND e.event IN ('reconocimiento', 'pago')
    AND EXISTS (SELECT 1 FROM public.fin_entries r WHERE r.reversal_of = e.id)
    AND public.fin_entry_reversal_residual(e.id) > 0.01
  LIMIT 1;
  IF v_entry IS NOT NULL THEN
    RAISE WARNING 'ERR_PARTIAL_REVERSAL_PENDING (intento bloqueado): recepción % con asiento % en reversión parcial y residual % CUP pendiente. Regularice el residual contable antes de anular (runbook RECT004 §regularización).',
      NEW.id, v_entry, v_residual;
    RAISE EXCEPTION 'ERR_PARTIAL_REVERSAL_PENDING: la recepción % tiene el asiento % con reversión parcial enlazada (residual % CUP sin compensar). Regularice primero el residual contable con un asiento explícito documentado (runbook RECT004 §regularización); después la anulación funcionará por el cauce ordinario.',
      NEW.id, v_entry, v_residual;
  END IF;
  RETURN NEW;
END;

DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL OR p_store_id IS NULL THEN
    RETURN false;
  END IF;

  -- Admin global tiene acceso a todo
  IF public.is_admin() THEN
    RETURN true;
  END IF;

  -- Verificar membership activa en la tienda
  RETURN EXISTS (
    SELECT 1
    FROM public.user_store_memberships m
    JOIN public.stores s
      ON s.id = m.store_id
    JOIN public.profiles p
      ON p.id = m.user_id
    WHERE m.user_id = v_user_id
      AND m.store_id = p_store_id
      AND m.status::text = 'active'
      AND (
        p.tenant_id IS NULL
        OR s.tenant_id IS NULL
        OR p.tenant_id = s.tenant_id
      )
  );
END;

BEGIN
    IF p_user_id IS NULL OR p_store_id IS NULL THEN RETURN false; END IF;

    -- [HSAA-20261027] Nivel administrativo de plataforma (admin|superadmin)
    -- delegado al check central is_admin_check(p_user_id) — la misma fuente
    -- confiable de is_admin()/RLS. Antes: v_role = 'admin' estricto, que
    -- rechazaba falsamente al superadmin (sin membresías por diseño).
    IF public.is_admin_check(p_user_id) THEN RETURN true; END IF;

    -- Check membership (usuarios operativos — semántica sin cambios)
    RETURN EXISTS (
        SELECT 1 FROM public.user_store_memberships
        WHERE user_id = p_user_id AND store_id = p_store_id AND status = 'active'
    );
END;

